INSERT OR IGNORE INTO `documents` (`id`,`dept_id`,`create_user_id`,`update_user_id`,`title`,`summary`,`content`,`category`,`status`,`share_scope`,`security_level`,`owner`,`uploader`,`version`,`review_due_at`,`ai_index_status`,`ai_indexed_at`,`is_deleted`,`create_time`,`update_time`) VALUES
(9101,1,9001,9001,'信息安全事件报告与处置规范','规定账号泄露、病毒感染、数据误发等安全事件的分级、报告时限和处置责任。','一、适用范围：全体员工及外包人员发现账号异常、恶意软件、敏感数据误发或设备遗失时，必须立即停止相关操作并保留现场。\n\n二、报告时限：重大事件应在15分钟内电话报告信息安全负责人，普通事件应在2小时内通过安全事件渠道登记。任何人员不得私自删除日志或对外披露。\n\n三、处置闭环：安全团队完成隔离、证据保全、影响评估和恢复验证；事件责任部门须在3个工作日内提交复盘及整改计划。','组织人事','ARCHIVED_ACTIVE','CROSS_DEPT','INTERNAL','顾宁','顾宁',3,'2027-01-15','INDEXED','2026-07-20 10:00:00',0,'2025-10-12 09:00:00','2026-07-20 10:00:00'),
(9102,1,9001,9001,'印章使用与保管管理办法','明确公章、合同章和法人章的申请材料、审批要求及保管责任。','印章由综合管理部指定专人双人复核管理。申请人须提交用印文件终稿、审批依据、份数和接收方信息。\n\n合同章必须关联已完成法务审查的合同编号；空白纸张、内容不完整文件不得用印。用印管理员核对文件与审批单一致后登记日期、经办人和印模。\n\n异地携章须经分管负责人批准，并由两人同行保管，返回当日完成归还登记。','组织人事','ARCHIVED_ACTIVE','DEPT','SENSITIVE','顾宁','顾宁',2,'2026-12-31','INDEXED','2026-07-18 14:20:00',0,'2026-01-08 11:00:00','2026-07-18 14:20:00'),
(9103,1,9001,9001,'公司级会议管理规范','统一经营会、项目例会和专项会议的议题收集、纪要与行动项管理。','会议发起人应至少提前1个工作日发布议程、目标和会前材料。无明确决策事项或信息同步可异步完成的，不安排会议。\n\n纪要须记录决策结论、责任人、完成时间及待确认风险，并在会后24小时内发送参会人员确认。行动项逾期由会议组织人提醒并升级至责任人主管。','组织人事','ARCHIVED_ACTIVE','CROSS_DEPT','INTERNAL','顾宁','顾宁',2,'2027-03-01','INDEXED','2026-07-17 09:30:00',0,'2026-02-10 09:00:00','2026-07-17 09:30:00'),
(9104,1,9001,9001,'纸质档案借阅管理细则（旧版）','旧版纸质档案借阅规则，已由新版档案数字化规范替代。','本文件已于2026年6月30日停止生效，仅用于历史审计。任何新增档案借阅均应执行现行档案数字化管理规范。','组织人事','EXPIRED_VOID','DEPT','INTERNAL','顾宁','顾宁',4,'2026-06-30','PENDING',NULL,0,'2024-04-15 09:00:00','2026-06-30 18:00:00'),
(9105,2,9002,9002,'产品需求评审与准入规范','定义PRD准入条件、评审角色、决策结论及需求变更规则。','需求进入研发排期前，产品经理必须补齐业务目标、目标用户、范围边界、交互原型、数据指标、验收标准和风险评估。\n\n评审至少包括产品、研发、测试、设计和数据代表。结论分为通过、有条件通过、退回补充三类；有条件通过项必须指定责任人与截止时间。\n\n评审通过后的重大范围变更须重新评估工期与风险，并在决策记录中保留变更原因。','产品研发','ARCHIVED_ACTIVE','CROSS_DEPT','INTERNAL','周屿','周屿',5,'2026-12-20','INDEXED','2026-07-25 16:00:00',0,'2025-11-02 10:00:00','2026-07-25 16:00:00'),
(9106,2,9002,9002,'生产环境发布与变更管理规范','规定发布窗口、风险分级、审批、灰度、回滚和发布后验证要求。','所有生产变更必须关联需求或缺陷编号，并记录影响范围、依赖项、验证方案和回滚步骤。高风险变更至少提前2个工作日组织评审。\n\n发布执行人和复核人不得为同一人。发布前确认监控、备份及回滚包可用；发布后30分钟内完成核心链路验证。\n\n出现核心指标异常、错误率持续上升或数据一致性风险时，应立即停止发布并执行回滚。','产品研发','ARCHIVED_ACTIVE','DEPT','SENSITIVE','周屿','周屿',4,'2026-11-15','INDEXED','2026-07-24 20:10:00',0,'2025-08-06 09:00:00','2026-07-24 20:10:00'),
(9107,2,9002,9002,'代码评审与合并请求规范','统一代码评审范围、检查项、审批人数和合并质量门禁。','所有进入主干或发布分支的代码必须通过合并请求，禁止直接推送。常规变更至少由1名非作者研发人员批准，核心模块至少需要2名指定维护人批准。\n\n评审重点包括正确性、安全性、异常处理、性能、可测试性和可维护性。自动化测试、静态检查或安全扫描失败时不得合并。\n\n作者应逐条回应评审意见；未解决的阻断意见不得通过口头约定绕过。','产品研发','ARCHIVED_ACTIVE','DEPT','INTERNAL','周屿','周屿',3,'2027-02-10','INDEXED','2026-07-22 13:40:00',0,'2026-01-05 09:00:00','2026-07-22 13:40:00'),
(9108,2,9002,9002,'线上故障分级与复盘规范','规定线上故障等级、响应时限、升级机制和无责复盘要求。','P0故障指核心业务完全不可用或发生重大数据安全风险，5分钟内响应并立即通知技术负责人；P1故障须在15分钟内响应。\n\n处置期间以恢复服务为首要目标，建立统一指挥与时间线，未经确认不得向外发布故障结论。\n\nP0/P1故障应在5个工作日内完成无责复盘，包括影响、时间线、根因、发现机制、处置过程和可验证整改项。','产品研发','ARCHIVED_ACTIVE','CROSS_DEPT','INTERNAL','周屿','周屿',2,'2027-01-20','INDEXED','2026-07-21 17:30:00',0,'2026-03-12 09:00:00','2026-07-21 17:30:00'),
(9109,3,9003,9003,'新员工入职与首月融入指南','覆盖报到材料、账号设备、培训、导师沟通和试用期目标确认。','入职前，HR确认劳动合同、身份证明、薪资卡及紧急联系人材料；行政完成工位和工牌准备，IT按岗位权限清单创建账号。\n\n入职首日完成信息安全、员工手册和合规培训；第一周与直属主管确认职责、协作关系及30天目标。\n\n第30天由员工、导师和主管进行融入回顾，记录需要补充的资源、培训与权限。','组织人事','ARCHIVED_ACTIVE','CROSS_DEPT','INTERNAL','林晓','林晓',3,'2027-01-15','INDEXED','2026-07-28 11:10:00',0,'2026-03-18 09:00:00','2026-07-28 11:10:00'),
(9110,3,9003,9003,'员工绩效目标与评估管理办法','明确目标制定、过程回顾、绩效评估、校准和申诉机制。','每个绩效周期开始后10个工作日内，员工与主管共同确认3至5项关键目标，并明确衡量口径、权重和完成标准。\n\n主管应至少每月进行一次进展回顾，绩效评价不得仅依据期末印象。部门校准会关注标准一致性，不得以强制比例替代事实评价。\n\n员工对结果有异议，可在结果沟通后5个工作日内向上一级主管或HR提交申诉。','组织人事','ARCHIVED_ACTIVE','DEPT','SENSITIVE','林晓','林晓',4,'2026-12-01','INDEXED','2026-07-26 09:15:00',0,'2025-12-01 09:00:00','2026-07-26 09:15:00'),
(9111,3,9003,9003,'招聘面试与候选人信息管理规范','规定招聘需求、面试评价、回避原则及候选人数据保护要求。','招聘启动前须完成岗位编制与职责确认。面试官应基于岗位胜任力提问，不得询问与工作无关的婚育、宗教、疾病等隐私信息。\n\n每轮面试结束后24小时内独立提交评价，避免先讨论后打分。候选人简历、联系方式和评价仅限招聘相关人员访问，不得下载至个人设备或用于其他目的。','组织人事','ARCHIVED_ACTIVE','DEPT','SENSITIVE','林晓','林晓',2,'2027-02-28','INDEXED','2026-07-19 15:20:00',0,'2026-04-02 09:00:00','2026-07-19 15:20:00'),
(9112,3,9003,9003,'年度培训与学习资源管理制度','拟定员工培训需求收集、课程采购、参训记录和效果评估规则。','本文件正在由人力行政部补充外部课程采购标准与培训效果评估口径，尚未提交部门审核，不作为现行制度执行依据。','组织人事','DRAFT','DEPT','INTERNAL','林晓','林晓',1,'2027-03-31','PENDING',NULL,0,'2026-07-29 10:00:00','2026-07-29 10:00:00'),
(9113,4,9004,9004,'客户分级与经营管理办法','依据客户价值、成长性、合作风险进行分级，并定义差异化服务策略。','客户分为战略、重点、成长和一般四级。分级依据包括年度收入贡献、增长潜力、行业影响力、回款情况和合作风险，每季度复核一次。\n\n战略客户须指定客户负责人和跨部门服务小组，形成年度经营计划；重点客户至少每月更新商机与风险。客户等级不得仅由单笔订单金额决定。','销售市场','ARCHIVED_ACTIVE','DEPT','INTERNAL','唐颖','唐颖',3,'2027-01-05','INDEXED','2026-07-23 10:30:00',0,'2025-10-20 09:00:00','2026-07-23 10:30:00'),
(9114,4,9004,9004,'商务报价与折扣授权规范','明确标准报价、折扣区间、特殊条款和审批授权边界。','标准产品原则上使用统一价目表。销售人员应填写产品范围、数量、服务周期、付款条件和折扣理由。\n\n低于指导价九折的报价须经销售负责人审核，低于八折或包含非标准交付承诺时还需财务及交付负责人会签。\n\n本版本正在等待销售市场部负责人审核，通过前不得作为正式授权依据。','销售市场','PENDING_DEPT_REVIEW','DEPT','SENSITIVE','唐颖','唐颖',2,'2026-12-15','PENDING',NULL,0,'2026-07-28 14:00:00','2026-07-29 09:20:00'),
(9115,4,9004,9004,'销售线索分配与跟进SOP','统一线索清洗、分配、首次响应、阶段更新和退回规则。','市场活动线索进入系统后，由运营按区域、行业和客户归属去重。高意向线索应在2小时内分配，销售在4个工作小时内完成首次有效联系。\n\n每次跟进须记录客户需求、关键人、预算、时间计划和下一步动作。连续5个工作日无跟进且无合理说明的线索，可回收至公共池重新分配。','销售市场','ARCHIVED_ACTIVE','DEPT','INTERNAL','唐颖','唐颖',2,'2027-02-18','INDEXED','2026-07-20 11:50:00',0,'2026-02-22 09:00:00','2026-07-20 11:50:00'),
(9116,4,9004,9004,'品牌内容对外发布规范','规定官网、公众号、新闻稿和社交媒体内容的品牌与合规审核。','对外内容必须使用最新品牌名称、标准标识和批准的产品表述。涉及客户名称、案例数据或合作关系时，应取得客户书面授权。\n\n产品能力、性能指标和市场排名必须有可追溯依据，不得使用绝对化或误导性表述。重大新闻稿需经品牌、业务负责人和法务审核后发布。','销售市场','ARCHIVED_ACTIVE','CROSS_DEPT','INTERNAL','唐颖','唐颖',5,'2027-03-10','INDEXED','2026-07-18 16:40:00',0,'2025-06-01 09:00:00','2026-07-18 16:40:00'),
(9117,5,9005,9005,'员工费用报销管理制度','明确费用真实性、票据要求、报销时限、费用标准和例外审批原则。','报销人对业务真实性和票据合法性负责。发票抬头、税号、金额和业务内容必须准确，电子发票不得重复报销。\n\n日常费用应在发生后30日内提交，跨年度费用原则上不得延至下一年度。超标准或缺少有效票据的费用，须说明原因并取得有权审批人确认。\n\n财务审核关注预算、制度标准、审批完整性和票据合规，不替代业务负责人对事项真实性的确认。','财务法务','ARCHIVED_ACTIVE','CROSS_DEPT','INTERNAL','苏晴','苏晴',4,'2027-02-01','INDEXED','2026-07-20 14:20:00',0,'2025-09-16 09:00:00','2026-07-20 14:20:00'),
(9118,5,9005,9005,'合同审查、签署与归档规范','覆盖合同模板选择、风险审查、签署授权、原件归档和到期提醒。','业务人员应优先使用公司标准合同模板。非标准条款须明确修改原因，涉及责任限制、知识产权、数据处理、自动续约或争议管辖的条款由法务重点审查。\n\n合同签署人必须具备有效授权，禁止倒签或先履行后补签。签署完成后5个工作日内上传完整扫描件并移交原件归档。\n\n合同负责人应维护履约节点、付款条件和续约日期，重大违约风险须及时报告。','财务法务','ARCHIVED_ACTIVE','CROSS_DEPT','SENSITIVE','苏晴','苏晴',3,'2026-12-28','INDEXED','2026-07-27 10:05:00',0,'2025-12-08 09:00:00','2026-07-27 10:05:00'),
(9119,5,9005,9005,'采购验收与付款管理办法','明确采购申请、订单、验收、发票和付款材料的一致性要求。','采购付款应满足申请、合同或订单、验收记录、发票四项信息一致。验收人不得与采购经办人为同一人，预付款须在合同中明确比例和保障措施。\n\n付款申请应在约定付款日前至少5个工作日提交。财务发现收款账户与合同主体不一致时应暂停付款并要求供应商出具有效说明。','财务法务','ARCHIVED_ACTIVE','DEPT','SENSITIVE','苏晴','苏晴',2,'2027-01-31','INDEXED','2026-07-24 12:10:00',0,'2026-02-16 09:00:00','2026-07-24 12:10:00'),
(9120,5,9005,9005,'年度预算编制与执行控制规范','规定预算编制口径、责任中心、调整机制和超预算控制原则。','各责任中心按年度经营目标编制人员、市场、采购和资本性支出预算，说明计算依据与业务假设。财务汇总后组织交叉复核，避免重复和遗漏。\n\n预算执行按月跟踪。单项支出超预算10%或新增未预算事项时，应提交预算调整说明；调整获批前不得以拆分订单等方式规避控制。','财务法务','ARCHIVED_ACTIVE','DEPT','INTERNAL','苏晴','苏晴',2,'2026-11-30','INDEXED','2026-07-16 09:45:00',0,'2026-01-12 09:00:00','2026-07-16 09:45:00');
--> statement-breakpoint

INSERT OR IGNORE INTO `document_versions` (`document_id`,`version`,`title`,`content`,`change_note`,`operator_user_id`,`operator`,`create_time`)
SELECT `id`,`version`,`title`,`content`,CASE `status` WHEN 'DRAFT' THEN '保存草稿' WHEN 'PENDING_DEPT_REVIEW' THEN '提交部门审核' WHEN 'EXPIRED_VOID' THEN '版本作废' ELSE '审核发布' END,`update_user_id`,`uploader`,`update_time`
FROM `documents` WHERE `id` BETWEEN 9101 AND 9120;
--> statement-breakpoint
INSERT OR IGNORE INTO `document_chunks` (`document_id`,`dept_id`,`document_version`,`chunk_index`,`content`,`embedding`,`embedding_model`,`is_active`,`create_time`)
SELECT `id`,`dept_id`,`version`,0,`title` || char(10) || `summary` || char(10) || `content`,NULL,NULL,1,`update_time`
FROM `documents` WHERE `id` BETWEEN 9101 AND 9120 AND `status`='ARCHIVED_ACTIVE';
--> statement-breakpoint
INSERT INTO `audit_logs` (`document_id`,`dept_id`,`action`,`actor_user_id`,`actor`,`detail`,`request_id`,`create_time`)
SELECT `id`,`dept_id`,CASE `status` WHEN 'DRAFT' THEN 'CREATE' WHEN 'PENDING_DEPT_REVIEW' THEN 'SUBMIT' WHEN 'EXPIRED_VOID' THEN 'ARCHIVE' ELSE 'APPROVE' END,`update_user_id`,`uploader`,'企业知识样例初始化','demo-corpus-20260731',`update_time`
FROM `documents` WHERE `id` BETWEEN 9101 AND 9120;
